+                })
+            })
+            .collect(),
+    };
+    let mut search = Search::new(Arc::new(state.clone()));
+    assert!(search.refinement.get().is_none());
+    assert!(!search.step());
+    assert!(search.refinement.get().is_some());
+    verify(state);
+}
