from pathlib import Path
import json
import subprocess

root = Path('/tmp/photonic-report')
record = []
for iteration in range(3):
    for name, argument in (('symmetry', []), ('inspection', ['--length', '32', '--sample', '21'])):
        row = {'name': name, 'round': iteration, 'argument': argument}
        for version in (('before', 'after') if iteration % 2 == 0 else ('after', 'before')):
            row[version] = json.loads(subprocess.check_output([str(root / version / name), *argument], text=True))
        record.append(row)
        (root / 'control.json').write_text(json.dumps(record, indent=2))
